INSERT INTO `sdb_articles` (`article_id`, `node_id`, `title`, `content`, `uptime`, `ifpub`, `align`, `filetype`, `filename`, `orderlist`, `ordernum`, `pubtime`, `disabled`, `goodsinfo`) VALUES
(28, 100, '系统升级通知（周二）！', '<p>尊敬的用户，您好！ </p>\n <p>　　为了给广大用户提供更好的服务，拟在 2009年 6月 6日 12:30 － 14:00 做系统升级。 </p>\n <p>　　届时，页面会出现暂时不能使用的情况。 </p>\n <p>　　在此，衷心的感谢每位用户一贯以来对我们工作的支持和关注。 </p>', 1342514454, '1', NULL, NULL, NULL, NULL, 50, 1342514454, 'false', 'a:2:{s:9:"goodslink";i:0;s:7:"hotlink";i:0;}'),
(29, 100, '商品评论改版升级!', '首先，为了使得大家能更充分参与，我们将逐步放开对产品评论的资格限制， 顾客可以在购买商品后对商品进行评价，其他顾客还可以对评价进行是否好评的参与，得到较多用户好评的评论将得到更多的展示机会。', 1342514513, '1', NULL, NULL, NULL, NULL, 50, 1342514513, 'false', 'a:2:{s:9:"goodslink";i:0;s:7:"hotlink";i:0;}'),
(30, 100, '8月8日暂停货品出库', '<span>敬爱的顾客： <br/>我们将于下2009年8月8日进行内部货品盘点和整合，当天将暂停货品的出库，但是为了广大用户能够尽量在周一收到您\n周六晚间和周日下午 16：00 前 生成的有效本地订单 (外环外和外地订单将在周日下午发出，具体配送时间根据订单所选的货运方式而定) \n，将原有的上海外环线以内的一日二送改为一日一送的配送方式。 8月8日配送时间为上午9:00 至下午 18：00，由此为您带来的不便，还请您谅解。\n 届时我们将不提供上门自提，售后和送货等其他服务。 从2008年8月8日星期二起外环线以内的配送恢复为一日二送。 \n在此衷心的感谢各位顾客一贯以来对我们工作的支持和关注。</span>', 1342514558, '1', NULL, NULL, NULL, NULL, 50, 1342514558, 'true', 'a:2:{s:9:"goodslink";i:0;s:7:"hotlink";i:0;}'),
(31, 100, '智聚嘉亮相2013广交会', '2013年4月19日，第112届广交会第一期展圆满结束。本届广交会在电子展区共开设2了个展位，并对公司要求对展位进行了特装布展，本届展会公司推出了RK3066&nbsp; RK3188 炬力四核等方案<strong>平板电脑</strong>和多元化<strong>移动电源</strong>，力争在中高端市场站稳脚跟。<br/>\n展会期间由公司精英对平板电脑以及移动电源给客户们细心认真的讲解，期间吸引众多客户的眼球. 显然我司产品对于市场的反响和产品凸显优势赢得客户的极力认可。<br/>\n&nbsp;<br/>\n这次展会期间吸引了800余人国内乃至世界各地的经销商以及终端客户同时还有许多对我们产品感兴趣的客户有意向同公司展开深层次合作，可谓硕果累累；为公司进一步开阔国内外市场打下了良好的基础。', 1372131649, '1', NULL, NULL, NULL, NULL, 50, 1372131649, 'false', 'a:2:{s:9:"goodslink";i:0;s:7:"hotlink";i:0;}'),
(32, 100, '与跨国公司结盟--智聚嘉与深圳山水顺利签约', '发布时间:2013-05-14 08:41 &nbsp;&nbsp;文章来源:未知 &nbsp;&nbsp;作者:admin &nbsp;&nbsp;点击数:205次<br/>\n            \n            \n                &nbsp; 与跨国公司结盟，东莞智聚嘉与深圳山水（国际）科技有限公司合作顺利签约。<br/>\n&nbsp;<br/>\n&nbsp; 近日，深圳山水（国际）科技公司高层领导一行莅临东莞市智聚嘉电子科技有限公司，对东莞市智聚嘉电子科技有限公司进行深入的考察，双方确定了项目的合作意向，并签订了合作协议，双方互利共赢，形成战略合作伙伴关系。<br/>\n&nbsp;&nbsp;山水是全世界历史最悠久、规模最大的影音企业之一，创建于1944年。多年的成功运作使它成为国际电子电器制造方面的杰出典范，在世界80多个国家均\n有分支机构和研发中心，销售网络遍布全球100多个国家，1961年在证券交易所上市后"SANSUI"发展成为国际著名品牌。 \n1999年，山水影音产品开始进入中国市场，历经十多年的成功推广和销售，在中国市场取得了极大认可，销售网络达到30000多家，山水品牌形象在全国各\n地深入民心。&nbsp;<br/>\n&nbsp;&nbsp;&nbsp;&nbsp;2003年，山水巨资五千万成立山水电子(中国)有限公司，总部设在广东中山,负责山水品牌全线产品在中国的推广和销售，目前在华投资已超过五亿\n元人民币。山水电子(中国)有限公司以实力雄厚的总公司为后盾，拥有世界先进的科研体系，实行经营策略多元化，以全新的连锁直销模式成功运作旗下品牌，开\n创了与国外先进电声企业合作的先河。山水产品也从创业初期单元化的音响产品，发展成为集家庭影院、迷你音响、多媒体音响、蓝牙音响、户外电瓶音响、彩电、\n数码、影碟机、移动DVD、投影仪、通信、冰洗、小家电为一体的多元化国际电子品牌。山水”，这个推崇经典、简约的国际品牌以其不俗的品位，优质的产品内\n涵、完美周到的售后，服务于中国家电市场。', 1372131685, '1', NULL, NULL, NULL, NULL, 50, 1372131685, 'false', 'a:2:{s:9:"goodslink";i:0;s:7:"hotlink";i:0;}');
