INSERT INTO `sdb_systmpl` (`tmpl_name`, `content`, `edittime`, `active`) VALUES
('messenger:email/account-lostPw', '<div class="MessageBody">\n<div class="ExternalClass" id="MessageBodyText" style="BORDER-RIGHT: #ffffff 1px solid; BORDER-TOP: #ffffff 1px solid; BORDER-LEFT: #ffffff 1px solid; BORDER-BOTTOM: #ffffff 1px solid">\n<center>\n<div align="center"><a href="http://www.iamcar.com.cn/" target="_blank"></a></div>\n<center>\n<table cellspacing="0" cellpadding="0" width="582" align="center" border="0">\n<tbody><tr>\n<td width="1" bgcolor="#336699" rowspan="3">\n<img height="1" hspace="0" src="http://g-images.amazon.com/images/G/01/associates/transparent-pixel.gif" width="2" border="0"> </td>\n<td><table cellspacing="0" cellpadding="10" width="580" border="0"><tbody><tr>\n<td valign="top">\n<p><font face="Verdana, Arial, Helvetica, sans-serif"><font size="2"><strong>Dear </strong><{$uname}>&nbsp; <strong>,</strong><br/>\n<br/>\n您忘记密码了吗？为了保险起见，我们将您的密码更新成新密码，请查看右侧个人信息，看到新密码后，您可以立即登陆会员中心修改密码。</font></font></p>\n<p><font face="Verdana" size="2"></font><font face="Verdana, Arial, Helvetica, sans-serif"><font size="2"><br/>\n<strong>您可以随时进入会员中心查看或者更新个人资料</strong><br/>\n我们保证每一位客户资料的安全与保密，您可以随时进入会员中心查看和修改个人注册信息，我们也会即时的根据您的最新资料和您保持畅通的沟通。</font><font size="2"></font></font></p>\n<font face="Verdana, Arial, Helvetica, sans-serif"><font size="2">\n</font></font><p><font face="Verdana, Arial, Helvetica, sans-serif"><font size="2"><br/><br/></font><font size="1">找到喜欢的商品，分享购物的故事<br/>\n</font></font></p>\n</td><td valign="top">\n<table cellspacing="0" cellpadding="0" width="100%" bgcolor="#ffffff" border="0">\n<tbody><tr><td align="middle" width="190">&nbsp;\n<table cellspacing="0" cellpadding="1" width="100%" align="center" bgcolor="#336699" border="0">\n<tbody><tr><td>\n<table cellspacing="0" cellpadding="3" width="100%" align="center" bgcolor="#ffffff" border="0">\n<tbody><tr>\n<td align="middle" bgcolor="#e1edfe"><font face="Verdana, arial, helvetica, sans-serif" color="#003366" size="2"><strong>您的个人信息</strong><br/>\n<font size="1"><font size="2">请妥善保管个人注册信息</font> </font></font></td></tr><tr>\n<td bgcolor="#ffffee">\n<table cellspacing="0" cellpadding="2" width="100%" align="left" border="0">\n<tbody><tr>\n<td class="small"><font face="Verdana, Arial, Helvetica, sans-serif"><font size="2"><strong>用户名</strong>：<{$uname}></font></font></td></tr>\n<tr>\n<td class="small"><font face="Verdana, Arial, Helvetica, sans-serif"><font size="2"><strong>新密码</strong>：<{$passwd}></font></font></td></tr></tbody></table></td></tr>\n<tr>\n<td align="middle" bgcolor="#ffffee">&nbsp;</td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table><br/>\n<table cellspacing="0" cellpadding="1" width="190" bgcolor="#336699" border="0">\n<tbody><tr><td valign="top">\n<table cellspacing="0" cellpadding="2" width="100%" bgcolor="#ffffff" border="0">\n<tbody><tr><td>\n<table cellspacing="0" cellpadding="2" width="100%" bgcolor="#ffffff" border="0">\n<tbody><tr valign="top">\n<td bgcolor="#e1edfe"><font face="Verdana, arial, helvetica,\nsans-serif" color="#003366" size="2"><strong>推荐网站给朋友</strong></font></td></tr>\n<tr>\n<td><font face="Verdana, arial, helvetica, sans-serif" size="2">如果您喜欢本网站或者本期畅销的产品，可以发送一封e-mail 给您的朋友，推荐朋友加入我们的大家庭。 <br/>\n<img height="9" src="http://www.iamcar.com.cn/syssite/home/shop/1/images/13/orange-arrow.gif" width="10" border="0"></font></td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td>\n<td width="1" bgcolor="#336699" rowspan="3">\n<img height="1" hspace="0" src="http://g-images.amazon.com/images/G/01/associates/transparent-pixel.gif" width="2" border="0"> </td></tr>\n<tr valign="top">\n<td bgcolor="#336699">\n<img height="2" hspace="0" src="http://g-images.amazon.com/images/G/01/associates/transparent-pixel.gif" width="1" border="0"></td></tr>\n<tr valign="top"><td colspan="3">\n<table cellspacing="0" cellpadding="10" border="0"><tbody><tr>\n<td valign="top"><font face="Verdana, arial, helvetica, sans-serif" size="2">■重要信息：由于此邮件包含个人注册资料，请妥善保存！</font></td></tr></tbody></table></td></tr>\n<tr valign="top">\n<td width="580" bgcolor="#336699" colspan="3">\n<img height="2" hspace="0" src="http://g-images.amazon.com/images/G/01/associates/transparent-pixel.gif" width="1" border="0"></td></tr></tbody></table></center></center></div></div>', 1377235057, 'true'),
('messenger:msgbox/account-lostPw', '您忘记密码了吗？为了保险起见，我们将您的密码更新成新密码，新密码为：<{$passwd}>。看到新密码后，您可以立即登陆会员中心修改密码。', 1377235061, 'true'),
('../admin/view/order/print_sheet', '<table class="table_frame" width="90%" border="0" align="center" cellpadding="0" cellspacing="0">\n  <tr>\n    <td><table width="100%" border="0" cellspacing="0" cellpadding="0">\n      <tr>\n        <td class="td_frame"><table width="100%" border="0" cellpadding="0" cellspacing="0">\n        <tr><td width="40%"><{$orderInfo.order_id|barcode}></td>\n          <td style="font-size:16pt"><{if !$printContent.cart && $printContent.sheet}><strong><{$orderInfo.print_id}></strong><{/if}></td>\n          <td><div id="chk_print" class="noprint">\n          \n          <input name="chk_pic_print" type="checkbox" id="chk_pic_print1"  checked="checked" />\n            <label class="label_pic_print" for="chk_pic_print1"><{t}>打印图片<{/t}></label>\n            &nbsp;&nbsp;&nbsp;&nbsp;\n             <input name="chk_address" type="checkbox" id="chk_address"  checked="checked" />\n            <label class="label_pic_print" for="chk_address"><{t}>打印配送地址<{/t}></label>\n            </div></td>\n        </tr>\n          <tr>\n            <td colspan="2" width="70%"><p><{t}>订单号<{/t}><strong>：<{$orderInfo.order_id}></strong>\n</p>\n            \n            <p><{t}>日期：<{/t}><{$orderInfo.createtime|userdate}></p></td>\n            <td width="30%"><p><{t}>客户：<{/t}><{$orderInfo.ship_name}></p>\n            <p>\n            电话：<{$orderInfo.ship_tel}></p></td>\n          </tr>\n        </table></td>\n      </tr>\n    </table></td>\n  </tr>\n  \n  <tr>\n    <td class="td_frame"><table width="98%" border="0" align="center" cellpadding="0" cellspacing="0">\n      <tr class="table_data_title">\n        <td width="40px">No</td>\n        <td><{t}>货号<{/t}></td>\n        <{if $storeplace_display_switch==''true''}>\n        <td><{t}>货位<{/t}></td>\n        <{/if}>\n        <td><{t}>商品名称<{/t}></td>\n        <td align="center"><{t}>单价<{/t}></td>\n        <td width="50px" align="center"><{t}>数量<{/t}></td>\n        <td align="center"><{t}>配货状态<{/t}></td>\n      </tr>\n\n        <{foreach from=$goodsItem item=aGoods name="item"}>\n      <tr>\n        <td><{$smarty.foreach.item.iteration}></td>\n        <td><{$aGoods.bn}></td>\n        <{if $storeplace_display_switch==''true''}>\n          <td><{$aGoods.store_place}></td>\n          <{/if}>\n        <td><img class="product"width="50" height="50" align="absmiddle"  src="<{$aGoods.thumbnail_pic|default:$env.conf.site.default_thumbnail_pic|storager}>" /><{$aGoods.name}>\n        <{if count($aGoods.minfo)}>\n          <{foreach from=$aGoods.minfo item=minfo key=name}>\n          <br><{$minfo.label}>：<{$minfo.value}>\n          <{/foreach}>\n          <{/if}><{$aGoods.addon.adjname}>\n          </td>\n        <td align="center"><{$aGoods.price|cur}></td>\n        <td align="center"><{$aGoods.nums}></td>\n        <td align="center"><div style="height:10pt;width:10pt;border:1pt solid #000"></div></td>\n      </tr>\n        <{/foreach}>\n\n    </table></td>\n  </tr>\n  <tr>\n    <td ><table width="100%" border="0" align="center" cellpadding="0" cellspacing="0">\n      <tr>\n        <td width="50%" valign="top" style="height:150px;"><p><{t}>赠品：<{/t}><{foreach from=$giftsItem item=aGift}> <{$aGift.name}> <{/foreach}></p>\n\n         <p><{t}>备注：<{/t}><{$orderInfo.memo}></p></td>\n        <td width="50%" valign="top">\n        <div id="print_address">\n        <p><{t}>配　送：<{/t}><{$orderInfo.shipping}></p>\n          <p><{t}>收货人：<{/t}><{$orderInfo.ship_name}></p>\n          <p><{t}>电　话：<{/t}><{$orderInfo.ship_tel}></p>\n          <p><{t}>手　机：<{/t}><{$orderInfo.ship_mobile}></p>\n          <p><{t}>地　址：<{/t}><{$orderInfo.ship_addr}></p>   \n          <p><{t}>邮　编：<{/t}><{$orderInfo.ship_zip}></p>\n          </div>\n          </td>\n      </tr>\n    </table></td>\n  </tr>\n  \n  <tr>\n    <td style="height:100px;" ><h1><{t}>签字：<{/t}></h1></td>\n  </tr>\n  <tr>\n    <td style="height:30px; padding-bottom:50px;" align="right"><strong>Powered by N+1电子商务管理系统</strong></td>\n  </tr>\n</table>', 1379039068, 'true'),
('../admin/view/order/print_cart', '<table class="table_frame" width="800" border="0" align="center" cellpadding="0" cellspacing="0">\n  <tr>\n    <td><table width="100%" border="0" cellspacing="0" cellpadding="0">\n        <tr>\n          <td class="td_frame"><table width="100%" border="0" cellpadding="0" cellspacing="0">\n              <tr>\n                <td colspan="3" ></td>\n                <td><div id="chk_print1" class="noprint">\n                    <input name="chk_pic_print" type="checkbox" id="chk_pic_print"  checked="checked" />\n                    <label class="label_pic_print" for="chk_pic_print"><{t}>打印图片<{/t}></label>\n                  </div></td>\n              </tr>\n              <tr>\n                <td width="15%"><img src="<{$env.conf.site.logo|storager}>" width="150px" height="60" /></td>\n                <td width="20%" valign="bottom"><{$shop.url}></td>\n                <td width="35%" style="font-size:16pt"><{if $printContent.cart && $printContent.sheet}><strong><{$orderInfo.print_id}></strong><{/if}></td>\n                <td width="30%"><p><{t}>客户：<{/t}><{$orderInfo.ship_name}></p>\n                  <p> 电话：<{$orderInfo.ship_tel}></p></td>\n              </tr>\n            </table></td>\n        </tr>\n      </table></td>\n  </tr>\n  <tr>\n    <td class="td_frame" style="padding:10px 0;"><table width="98%" border="0" align="center" cellpadding="0" cellspacing="0">\n        <tr>\n          <td align="left"><h2><{t}>订单号：<{/t}><{$orderInfo.order_id}></h2></td>\n          <td align="right"><h2><{t}>订购日期：<{/t}><{$orderInfo.createtime|userdate}></h2></td>\n        </tr>\n      </table></td>\n  </tr>\n  <tr>\n    <td class="td_frame"><table width="98%" border="0" align="center" cellpadding="0" cellspacing="0">\n        <tr class="table_data_title">\n          <td width="8%">No</td>\n          <td width="15%"><{t}>货号<{/t}></td>\n          <td width="45%"><{t}>商品名称<{/t}></td>\n          <td width="12%"><{t}>单价<{/t}></td>\n          <td width="8%"><{t}>数量<{/t}></td>\n          <td width="12%"><{t}>小计<{/t}></td>\n        </tr>\n        <{foreach from=$goodsItem item=aGoods name="item_0"}>\n        <tr>\n          <td><{$smarty.foreach.item.iteration}></td>\n          <td><{$aGoods.bn}></td>\n          <td><img class="product" src="<{$aGoods.thumbnail_pic|default:$env.conf.site.default_thumbnail_pic|storager}>" width="50" height="50" align="absmiddle" /><{$aGoods.name}>\n            <{if count($aGoods.minfo)}>\n            <{foreach from=$aGoods.minfo item=minfo key=name}> <br>\n            <{$minfo.label}>：<{$minfo.value}>\n            <{/foreach}>\n            <{/if}><{$aGoods.addon.adjname}> </td>\n          <td><{$aGoods.price|cur}><{t}>元<{/t}></td>\n          <td><{$aGoods.nums}></td>\n          <td><{$aGoods.price*$aGoods.nums|cur}><{t}>元<{/t}></td>\n        </tr>\n        <{/foreach}>\n    </table></td>\n  </tr>\n  <tr>\n    <td class="td_frame"><table width="100%" border="0" align="center" cellpadding="0" cellspacing="0">\n        <tr>\n          <td width="70%" valign="top" style=" padding:20px 0;"><p><{t}>赠品：<{/t}><{foreach from=$giftsItem item=aGift}> <{$aGift.name}> <{/foreach}></p>\n            <p><{t}>订单附言：<{/t}><{$orderInfo.memo}></p></td>\n          <td width="30%" valign="top"><p><{t}>商品总价：<{/t}><{$orderInfo.cost_item|cur}></p>\n            <p><{t}>配送费用：<{/t}><{$orderInfo.cost_freight|cur}></p>\n            <p><{t}>保价费用：<{/t}><{$orderInfo.cost_protect|cur}></p>\n            <p><{t}>支付手续费：<{/t}><{$orderInfo.cost_payment|cur}></p>\n            <p><{t}>订单优惠：<{/t}><{$orderInfo.self|cur}></p></td>\n        </tr>\n      </table></td>\n  </tr>\n  <tr>\n    <td class="td_frame" style="padding:15px 0;"><table width="100%" border="0" align="center" cellpadding="0" cellspacing="0">\n        <tr>\n          <td width="40%"><p><{t}>服务商：<{/t}><{$shop.name}></p>\n            <p><{t}>电话：<{/t}><{$shop.tel}></p>\n            <p><{t}>邮箱：<{/t}><{$shop.email}></p>\n            <p><{t}>网址：<{/t}><{$shop.url}></p></td>\n          <td width="30%"><img src="/images/wxin.png" width="80"/></td>\n          <td width="30%" valign="top"><h2><{t}>应付总金额：<{/t}><{$orderInfo.total_amount|cur}><{t}>元<{/t}></h2></td>\n        </tr>\n      </table></td>\n  </tr>\n  <tr>\n    <td class="td_frame" style="padding:15px 0;">您目前的总积分为 <{$memberPoint}> ，累计购物<{$orderSum.sum}>次，累计购物金额<{$orderSum.sum_pay|cur}>元 </td>\n  </tr>\n  <tr><td><table width="100%" border="0" cellspacing="0" cellpadding="0"><tr>\n    <td width="60%" style="height:20px; padding:10px 0 30px;" align="left">如果你满意,请悄悄地告诉朋友;如果你不满意,请大声地告诉我们.谢谢你的惠顾!</td>\n    <td width="40%" style="height:20px; padding:10px 0 30px;" align="right"><strong>Powered by N+1电子商务管理系统</strong></td></tr></table></td>\n  </tr>\n</table>', 1379039068, 'true'),
('misc/orderprint', '<{$order.page1}>\n<table width="100%" border="0" cellpadding="2" cellspacing="0" >\n  <tr> \n    <td width="3%" height="59" valign="middle"><strong><br>\n      </strong></td>\n    <td width="40%" valign="middle" ><strong><{t}>订单信息<{/t}><br>\n      </strong></td>\n    <td width="47%" align="right" valign="bottom" ><strong><span ><{$order.shopname}></span></strong><br>\n      地址：<{$order.shopaddress}><br>\n      <span ><{t}>电话：<{/t}><{$order.shoptelphone}></span>\n      <br />\n\n      <{t}>邮编：<{/t}><{$order.shopzip}></td>\n  </tr>\n</table>\n<table width="100%" border="0" cellspacing="0" cellpadding="0">\n  <tr>\n    <td>&nbsp;</td>\n  </tr>\n</table>\n<{if count($order.goodsItems) > 0}>\n<table width="100%" border="0" cellpadding="2" cellspacing="0" >\n  <tr> \n    <td ><strong><{t}>商品信息<{/t}></strong><hr size="1" noshade></td>\n  </tr>\n</table>\n<table width="98%" border="0" cellpadding="2" cellspacing="0" bgcolor="#F7F7F7" >\n  <tr>\n    <td width="64" height="26" align="center" ><{t}>货号<{/t}></td>\n    <td width="325" height="26" align="center" ><{t}>商品名称<{/t}><br>    </td>\n    <td width="325" height="26" align="center"><{t}>商品分类<{/t}><br>    </td>\n    <td width="120" height="26" align="center"><{t}>价格<{/t}><br>    </td>\n    <td width="90" height="26" align="center" ><{t}>数量<{/t}></td>\n    <td width="90" height="26" align="center" ><{t}>小计<{/t}></td>\n  </tr>\n  <{foreach from=$order.goodsItems item=item}>\n  <tr> \n    <td width="64" align="center" height="20"><{$item.bn}></td>\n    <td width="325" align="center" height="20"><{$item.name}></td>\n    <td width="325" align="center" height="20"><{$item.catname}></td>\n    <td width="120" align="center" height="20"><{$item.price|cur}></td>\n    <td width="90" align="center" height="20"><{$item.nums}></td>\n    <td width="90" align="center" height="20"><{$item.amount|cur}></td>\n  </tr>\n  <{/foreach}>\n</table>\n<{/if}>\n<{if count($order.giftItems) > 0}>\n<table width="100%" border="0" cellpadding="2" cellspacing="0" >\n  <tr> \n    <td ><strong><{t}>赠品信息<{/t}></strong><hr size="1" noshade></td>\n  </tr>\n</table>\n<table width="98%" border="0" cellpadding="2" cellspacing="0" bgcolor="#F7F7F7" >\n  <tr> \n    <td width="325" height="26" align="center" ><{t}>赠品名称<{/t}><br>    </td>\n    <td width="120" height="26" align="center"><{t}>所需积分<{/t}><br>    </td>\n    <td width="120" height="26" align="center" ><{t}>购买量<{/t}></td>\n    </td>\n  </tr>\n  <{foreach from=$order.giftItems item=gftitem}>\n  <tr> \n    <td width="325" align="center" height="20"><{$gftitem.name}></td>\n    <td width="120" align="center" height="20"><{$gftitem.point}></td>\n    <td width="120" align="center" height="20"><{$gftitem.nums}></td>\n    <td></td>\n  </tr>\n  <{/foreach}>\n</table>\n<{/if}>\n<table width="100%" border="0" cellpadding="2" cellspacing="0" >\n  <tr> \n    <td ><strong><{t}>订单信息<{/t}></strong><hr size="1" noshade></td>\n  </tr>\n</table>\n<table width="100%" border="0" cellspacing="0" cellpadding="4"    bgcolor="#F7F7F7">\n  <tr> \n    <td width="18%" align="right" nowrap ><{t}>订单号：<{/t}></td>\n    <td width="27%" nowrap><{$order.order_id}></td>\n    <td width="16%" align="right" nowrap ><{t}>状态：<{/t}></td>\n    <td width="39%" nowrap><{if $order.pay_status == 0}>未支付<{elseif $order.pay_status == 1}>已支付<{elseif $order.pay_status == 2}>处理中<{elseif $order.pay_status == 3}>部分付款<{elseif $order.pay_status == 4}>部分退款<{elseif $order.pay_status == 5}>已退款<{/if}>\n      [<{if $order.ship_status == 0}>未发货<{elseif $order.ship_status == 1}>已发货<{elseif $order.ship_status == 2}>部分发货<{elseif $order.ship_status == 3}>部分退货<{elseif $order.ship_status == 4}>已退货<{/if}>]</td>\n  </tr>\n  <tr> \n    <td width="18%" align="right" valign="top" nowrap ><{t}>下单日期：<{/t}></td>\n    <td width="27%" nowrap><{$order.createtime|cdate:''SDATE_STIME''}></td>\n    <td width="16%" align="right" valign="top" nowrap ><{t}>商品总额：<{/t}></td>\n    <td width="39%" nowrap><{$order.cost_item|cur}></td>\n  </tr>\n  <{if $order.is_delivery == ''Y''}>\n  <tr> \n    <td width="18%" align="right" valign="top" nowrap ><{t}>配送方式：<{/t}></td>\n    <td width="27%" nowrap><{$order.shipping}></td>\n    <td width="16%" align="right" valign="top" nowrap ><{t}>配送费用：<{/t}></td>\n    <td width="39%" nowrap><{$order.cost_freight|cur}></td>\n  </tr>\n  <tr>\n    <td align="right" valign="top" nowrap ><{t}>是否保价：<{/t}></td>\n    <td nowrap><{if $order.is_protect == true}><{t}>是<{/t}><{else}><{t}>否<{/t}><{/if}></td>\n    <td align="right" valign="top" nowrap ><{t}>保价费用：<{/t}></td>\n    <td nowrap><{$order.cost_protect|cur}></td>\n  </tr>\n  <{/if}>\n  <tr> \n    <td align="right" valign="top" nowrap ><{t}>商品重量：<{/t}></td>\n    <td nowrap><{$order.weight}></td>\n    <td align="right" valign="top" nowrap ><{t}>订单总金额：<{/t}></td>\n    <td nowrap><{$order.total_amount|cur}></td>\n  </tr>\n  <tr> \n    <td align="right" valign="top" nowrap ><{t}>支付方式：<{/t}></td>\n    <td nowrap><{$order.payment}></td>\n    <td align="right" valign="top" nowrap ><{t}>支付手续费：<{/t}></td>\n    <td nowrap><{$order.cost_payment|cur}></td>\n  </tr>\n  <tr > \n    <td align="right" valign="top" nowrap ><{t}>货币：<{/t}></td>\n    <td nowrap><{$order.currency}></td>\n    <td align="right" valign="top" nowrap ><{t}>支付总金额：<{/t}></td>\n    <td nowrap><{$order.final_amount}></td>\n  </tr>\n  <{if $order.is_tax == ''true''}>\n  <tr > \n    <td align="right" valign="top" nowrap ><{t}>发票税额：<{/t}></td>\n    <td nowrap><{$order.cost_tax|cur}></td>\n    <td align="right" valign="top" nowrap ><{t}>发票抬头：<{/t}></td>\n    <td nowrap><{$order.tax_company}></td>\n  </tr>\n  <{/if}>\n</table>\n\n<table width="100%" border="0" cellpadding="2" cellspacing="0" >\n  <tr> \n    <td ><strong><{t}>购货人<{/t}></strong><hr size="1" noshade></td>\n  </tr>\n</table>\n<table width="100%" border="0" cellspacing="0" cellpadding="4"    bgcolor="#F7F7F7">\n  <tr> \n    <td width="18%" align="right" valign="top" nowrap ><{t}>姓名：<{/t}></td>\n    <td width="27%" nowrap><{$order.member.name}></td>\n    <td width="16%" align="right" valign="top" nowrap ><{t}>用户名：<{/t}></td>\n    <td width="39%" nowrap><{$order.member.uname}></td>\n    <td width="39%" align="right" nowrap><{t}>电话：<{/t}></td>\n    <td width="39%" nowrap><{$order.member.tel}></td>\n  </tr>\n  <tr> \n    <td width="18%" align="right" valign="top" nowrap ><{t}>邮编：<{/t}></td>\n    <td width="27%" nowrap><{$order.member.zip}></td>\n    <td width="16%" align="right" valign="top" nowrap >Email：</td>\n    <td width="39%" nowrap><{$order.member.email}></td>\n    <td width="39%" align="right" nowrap><{t}>地址：<{/t}></td>\n    <td width="39%" nowrap><{$order.member.addr}></td>\n  </tr>\n  \n  <tr> \n    <td width="18%" align="right" valign="top" nowrap ><{t}>附言：<{/t}></td>\n    <td nowrap><{$order.memo}></td>\n    <td align="right" valign="top" nowrap>&nbsp;</td>\n    <td nowrap>&nbsp;</td>\n    <td align="right" nowrap>&nbsp;</td>\n    <td nowrap>&nbsp;</td>\n  </tr>\n</table>\n<{if $order.is_delivery == ''Y''}>\n<table width="100%" border="0" cellpadding="2" cellspacing="0" >\n  <tr> \n    <td ><strong><{t}>收货人<{/t}></strong><hr size="1" noshade></td>\n  </tr>\n</table>\n<table width="100%" border="0" cellspacing="0" cellpadding="4"    bgcolor="#F7F7F7">\n  <tr> \n    <td width="18%" align="right" valign="top" nowrap ><{t}>姓名：<{/t}></td>\n    <td width="27%" nowrap><{$order.ship_name}></td>\n    <td width="16%" align="right" valign="top" nowrap >Email：</td>\n    <td width="39%" nowrap><{$order.ship_email}></td>\n    <td width="39%" align="right" nowrap><{t}>邮编：<{/t}></td>\n    <td width="39%" nowrap><{$order.ship_zip}></td>\n  </tr>\n  <tr> \n    <td width="18%" align="right" valign="top" nowrap ><{t}>电话：<{/t}></td>\n    <td width="27%" nowrap><{$order.ship_tel}></td>\n    <td width="16%" align="right" valign="top" nowrap ><{t}>手机：<{/t}></td>\n    <td width="39%" nowrap > \n      <{$order.ship_mobile}></td>\n    <td width="39%" align="right" nowrap ><{t}>送货时间：<{/t}></td>\n    <td width="39%" nowrap ><{$order.ship_time}></td>\n  </tr>\n  \n  <tr> \n    <td align="right" valign="top" nowrap ><{t}>送货地址：<{/t}></td>\n    <td nowrap><{$order.ship_addr}></td>\n    <td align="right" nowrap>&nbsp;</td>\n    <td align="right" nowrap>&nbsp;</td>\n    <td align="right" nowrap>&nbsp;</td>\n    <td align="right" nowrap>&nbsp;</td>\n  </tr>\n</table>\n<{/if}>', 1379039068, 'true');
